<?php
declare(strict_types=1); require_once __DIR__.'/auth.php'; require_login(); $pdo=db(); if(!table_exists($pdo,'calendar_events')) redirect('upgrade_phase2.php'); $msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=post_string('title');$date=post_string('event_date');if($title&&$date){$st=$pdo->prepare('INSERT INTO calendar_events(title,description,event_date,event_time,recurrence,assigned_user_id) VALUES(?,?,?,?,?,?)');$st->execute([$title,post_string('description')?:null,$date,post_string('event_time')?:null,post_string('recurrence','none'),post_int('assigned_user_id')?:null]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','calendar',$id,'Calendar event created: '.$title);flash('success','Calendar event added.');}redirect('calendar.php');}
$rows=$pdo->query("SELECT e.*,TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) user_name FROM calendar_events e LEFT JOIN users u ON u.id=e.assigned_user_id WHERE e.event_date>=CURDATE()-INTERVAL 30 DAY ORDER BY e.event_date,e.event_time LIMIT 200")->fetchAll();$users=$pdo->query("SELECT id,first_name,last_name FROM users WHERE status='active' ORDER BY first_name")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendar · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1050px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px;margin-bottom:16px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:10px 14px;border-radius:8px;font-weight:bold}.row{display:flex;justify-content:space-between;gap:20px;padding:13px 0;border-bottom:1px solid #edf0f5}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}</style></head><body><header class="top"><strong>SPS CRM · Calendar</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="card"><h2>Add Event</h2><form method="post"><?=csrf_field()?><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Date</label><input type="date" name="event_date" required value="<?=date('Y-m-d')?>"></div><div class="field"><label>Time</label><input type="time" name="event_time"></div><div class="field"><label>Recurrence</label><select name="recurrence"><option>none</option><option>daily</option><option>weekly</option><option>monthly</option><option>yearly</option></select></div><div class="field"><label>Assigned user</label><select name="assigned_user_id"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['first_name'].' '.$u['last_name'])?></option><?php endforeach;?></select></div><button class="btn">Add Event</button></form></div><div class="card"><h2>Upcoming & Recent Events</h2><?php foreach($rows as $r):?><div class="row"><div><strong><?=e($r['title'])?></strong><div><?=e($r['description']?:'')?></div></div><div><strong><?=e($r['event_date'])?></strong> <?=e(substr((string)$r['event_time'],0,5))?><div><?=e($r['recurrence'])?></div></div></div><?php endforeach;?><?php if(!$rows):?><div>No events yet.</div><?php endif;?></div></main></body></html>
